#!/usr/bin/env bash
# Two release lines decide from paths whether a commit releases: a commit since the line's newest
# tag that touches one of the paths its version step hands `release-push.sh version` releases, and
# any other commit releases nothing. Both lines ship Go binaries, so a file their build reads that
# those paths leave out changes what ships and releases nothing. This check holds the paths of
# both lines to what go says the builds read.
#
# THE LEGION LINE, release.yaml's legion_build: the paths after `--` in $LEGION_VERSION_ARGS,
# written by hand, and then $LEGION_GO_INPUTS. The binary compiles in packages of the envoy module
# too, and those were a list kept by hand that fell behind: main at 4055c4a523 named 14 of the 17
# packages/envoy packages `go list -deps ./cmd/legion` names, so a change to internal/ctxlock,
# internal/dispatch/bytelru or internal/fold changed the binary and released nothing (INFRA-3904).
# So $LEGION_GO_INPUTS is a generated block of release.yaml's workflow `env:`, from a
# `# BEGIN generated by ...` line to `# END generated`, holding every path go names for the
# binary (below) that no path of $LEGION_VERSION_ARGS covers, one a line, sorted. The listings
# are `go list -deps ./cmd/legion` in packages/daemon for each target of
# .github/go-release-targets.json's `legion` list under CGO_ENABLED=0, as the Build legion step
# compiles it: a file that one target's build constraints alone compile can import a package
# that no other target links.
#
# THE LEGION-ENVOY LINE, release-envoy-listener.yaml's release_build and release_publish: the
# paths after `--` in $LEGION_ENVOY_VERSION_ARGS, written by hand. They name packages/envoy/
# whole, so no block lists its packages; the check holds those paths to cover every path go
# names for the archives the workflow compiles on the runner, in packages/envoy under the root
# go.work: envoy-listener for linux and each arch of .github/go-release-targets.json's `envoy`
# list, under CGO_ENABLED=0 and 1 both, since the build job leaves it to the runner;
# agent-secrets and agent-secrets-helper for the same under CGO_ENABLED=0; and agent-secrets for
# each target of .github/agent-secrets-client-targets.json under CGO_ENABLED=0. The image builds
# from packages/envoy's own module files, with no go.work, and its inputs are
# .github/scripts/check-image-trigger-paths.sh's to hold.
#
# What go names for a listing, on either line:
#   * the directory of every package of this repository it names. A directory stands for the
#     package's files, its embedded ones among them, since go:embed reads nothing outside it;
#   * the files that decide which version of each module the binary links: the workspace's go.work
#     and go.work.sum (`go env GOWORK`), and the go.mod and go.sum of every module `go list -m`
#     names there and of every module that provides one of those packages, each one that exists.
# A path covers itself and the tree under it, as a git pathspec does. An exclude (`:(exclude)X`,
# `:!X` or `:^X`) drops what it matches from every release whatever else names it.
#
# Fails on:
#   1. a LEGION_GO_INPUTS block that is not exactly the one `write` writes, naming every path it
#      lacks and every path it names that go does not, or a release.yaml with no such block or
#      more than one;
#   2. a block that is not the LEGION_GO_INPUTS of release.yaml's workflow `env:`;
#   3. legion_build's version step not handing the block to `release-push.sh version legion-v`
#      right after $LEGION_VERSION_ARGS, since then no release reads it;
#   4. a path go names for the legion-envoy archives that no path of $LEGION_ENVOY_VERSION_ARGS
#      covers, naming it and the listing that names it;
#   5. a path go names for either line that an exclude of that line's paths drops, or a path
#      written with any other pathspec magic, which this check cannot read;
#   6. a go command that fails, a package of this repository that go list cannot load, or a
#      listing that does not name the program it lists, since what that program links is then
#      unknown and a listing of nothing would pass everything.
#
# The go commands run through .github/scripts/go_offline.py, as check-ci-filters.sh's do, and that
# module says why: with GOPROXY=off over an empty module cache, so nothing is downloaded and a
# cold runner gives the answer a warm machine does. A third-party package then fails to load,
# which loses no package of this repository, since no module outside it imports one. The
# toolchain each module pins is resolved first, under this machine's own cache and proxy, and its
# own binary runs every go command under GOTOOLCHAIN=local.
#
# THE TWO MODES. `check`, the default a bare call takes, is every refusal above. `write` rewrites
# the block in release.yaml instead of refusing rule 1, and refuses everything else as `check`
# does; it writes nothing when rule 5 or 6 refuses for the legion line, since the block would then
# be computed from a set that is unknown. It writes only inside the block. Any other word, or more
# than one, fails.
#
# Run from anywhere: .github/scripts/check-legion-version-inputs.sh
#                    .github/scripts/check-legion-version-inputs.sh write
# CI runs it in ci.yaml's ci-filters job, and its tests in ci.yaml's test job.
set -euo pipefail

cd "$(dirname "$0")/../.."

# A bare call checks: a caller who says nothing is asking for the verdict, never for a rewrite of
# release.yaml.
case "$#:${1:-}" in
  0: | 1:check | 1:write) ;;
  *)
    echo "::error file=.github/scripts/check-legion-version-inputs.sh::this check takes one optional mode: \`check\` (the default) refuses a LEGION_GO_INPUTS block of release.yaml that is not what go names, and \`write\` writes that block instead. Run \`.github/scripts/check-legion-version-inputs.sh\` or \`.github/scripts/check-legion-version-inputs.sh write\`." >&2
    exit 1
    ;;
esac

# go_offline.py sits beside this script in the repository it checks. PYTHONDONTWRITEBYTECODE keeps
# the import from leaving a __pycache__ in the tree.
PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=.github/scripts exec python3 - "${1:-check}" <<'PY'
import json
import re
import shutil
import sys
import tempfile
from pathlib import Path

import yaml

import go_offline
from go_offline import decode_stream

MODE = sys.argv[1]
SELF = ".github/scripts/check-legion-version-inputs.sh"
RELEASE = ".github/workflows/release.yaml"
LISTENER = ".github/workflows/release-envoy-listener.yaml"
TARGETS = ".github/go-release-targets.json"
CLIENT_TARGETS = ".github/agent-secrets-client-targets.json"
DAEMON = "packages/daemon"
ENVOY = "packages/envoy"
HAND = "LEGION_VERSION_ARGS"
ENVOY_ARGS = "LEGION_ENVOY_VERSION_ARGS"
BLOCK = "LEGION_GO_INPUTS"
JOB = "legion_build"
STEP_ID = "version"
HANDOFF = f".github/scripts/release-push.sh version legion-v ${HAND} ${BLOCK}"
BEGIN = f"  # BEGIN generated by `{SELF} write`"
END = "  # END generated"
HEAD = [
    f"{BEGIN}: what go",
    f"  # decides the binary from beyond ${HAND}'s paths, one path a line. An edit by",
    "  # hand is refused: that check, which the ci-filters job runs, names what go adds or drops.",
]
# git's exclude magic, long and short: `:(exclude)X`, `:!X` and `:^X`.
EXCLUDE = re.compile(r":(?:\(exclude\)|!|\^)(.+)")
REPO = Path.cwd().resolve()
problems = []


def annotation(path, message, line=None):
    where = f"file={path}" + (f",line={line}" if line else "")
    return f"::error {where}::{message}"


def problem(message, path, line=None):
    problems.append(annotation(path, message, line))


def fatal(message, path):
    """Stop on `message`, printing the problems found before it too, so none is lost."""
    print("\n".join([*problems, annotation(path, message)]), file=sys.stderr)
    raise SystemExit(1)


def report_and_stop_on_problems():
    if problems:
        print("\n".join(problems), file=sys.stderr)
        raise SystemExit(1)


def read(path):
    try:
        return Path(path).read_text(encoding="utf-8")
    except FileNotFoundError:
        fatal(f"{path} is missing", path)
    except UnicodeDecodeError as error:
        fatal(f"{path} is not readable as text: {error.reason}", path)


def load(path, text):
    try:
        return yaml.safe_load(text)
    except yaml.YAMLError as error:
        fatal(f"{path} is not YAML this check can read: {' '.join(str(error).split())}", path)


def rel(path):
    return go_offline.relative(path, REPO)


def covers(spec, path):
    """Whether the plain pathspec `spec` matches `path`, a file or a directory written with its /."""
    spec, path = spec.rstrip("/"), path.rstrip("/")
    return path == spec or path.startswith(spec + "/")


def env_of(path, doc):
    env = doc.get("env") if isinstance(doc, dict) else None
    return env if isinstance(env, dict) else {}


def pathspecs(path, doc, key):
    """The paths after `--` in the workflow env's `key`: the plain ones, and each exclude as
    (its text, the path it drops). Any other magic is refused."""
    value = env_of(path, doc).get(key)
    if not isinstance(value, str):
        fatal(f"{path}'s workflow env: holds no {key} string", path)
    words = value.split()
    if "--" not in words:
        fatal(f"{path}'s {key} has no `--`, after which release-push.sh version reads its paths", path)
    plain, excludes = [], []
    for word in words[words.index("--") + 1:]:
        if not word.startswith(":"):
            plain.append(word)
        elif match := EXCLUDE.fullmatch(word):
            excludes.append((word, match.group(1)))
        else:
            problem(f"{key} names `{word}`, a pathspec with magic this check cannot read: it reads "
                    f"plain paths and excludes alone, and cannot say what this one leaves out", path)
    return plain, excludes


def targets(path, key, pairs):
    """The list `key` of the target file `path`: os/arch pairs, or bare arches."""
    try:
        listed = json.loads(read(path))[key]
    except (ValueError, KeyError, TypeError):
        listed = None
    if not isinstance(listed, list) or not listed or not all(
            isinstance(t, str) and t.count("/") == (1 if pairs else 0) for t in listed):
        fatal(f"{path} holds no `{key}` list of {'os/arch targets' if pairs else 'arches'}", path)
    return listed


class Go:
    """The go commands of one module directory, under the toolchain that directory pins."""

    def __init__(self, workdir, modcache):
        self.workdir, self.modcache = workdir, modcache
        try:
            self.binary, stderr = go_offline.toolchain(workdir)
        except FileNotFoundError:
            fatal(f"no go on PATH, so what {workdir}'s programs link is unknown", SELF)
        if not self.binary:
            fatal(f"`go env GOROOT` in {workdir} names no toolchain ({' '.join(stderr.split())[:500]}), "
                  f"so what its programs link is unknown", SELF)

    def __call__(self, args, **extra):
        result = go_offline.run(self.binary, args, self.workdir, self.modcache, extra)
        if result.returncode != 0:
            fatal(f"in {self.workdir}, go {' '.join(args)} failed, so what it lists is unknown: "
                  f"{' '.join(result.stderr.split())[:500]}", SELF)
        return result.stdout


def named(go, listings):
    """Every path go names for `listings` - (packages, env, label) each - mapped to the label of
    the first listing that names it: package directories with their /, and module files."""
    modules = [line.split("\t") for line in go(["list", "-m", "-f", "{{.Path}}\t{{.GoMod}}"]).splitlines() if line]
    first_party = [module for module, _ in modules]
    paths, gomods = {}, {gomod: f"go list -m in {go.workdir}" for _, gomod in modules if gomod}
    gowork = go(["env", "GOWORK"]).strip()
    files = {gowork: f"go env GOWORK in {go.workdir}", gowork + ".sum": f"go env GOWORK in {go.workdir}"} \
        if gowork and gowork != "off" else {}
    for packages, env, label in listings:
        listing = decode_stream(go(["list", "-e", "-deps", "-json=ImportPath,Dir,Module,Error", *packages], **env))
        dirs = {Path(pkg["Dir"]).resolve() for pkg in listing if pkg.get("Dir")}
        for package in packages:
            if (REPO / go.workdir / package).resolve() not in dirs:
                fatal(f"go list -deps {package} in {go.workdir} for {label} named no package in its directory, "
                      f"so what it links is unknown", SELF)
        for pkg in listing:
            name = pkg.get("ImportPath", "")
            directory = rel(pkg["Dir"]) if pkg.get("Dir") else None
            ours = directory is not None or any(name == m or name.startswith(m + "/") for m in first_party)
            if ours and pkg.get("Error"):
                problem(f"go list cannot load {name} for {label}, so what it links is unknown: "
                        f"{' '.join(str(pkg['Error'].get('Err', '')).split())[:500]}", SELF)
            if directory is None:
                continue
            paths.setdefault(directory + "/", label)
            if (pkg.get("Module") or {}).get("GoMod"):
                gomods.setdefault(pkg["Module"]["GoMod"], label)
    for gomod, label in gomods.items():
        files.setdefault(gomod, label)
        files.setdefault(str(Path(gomod).parent / "go.sum"), label)
    for path, label in files.items():
        if Path(path).is_file() and rel(path):
            paths.setdefault(rel(path), label)
    return paths


def refuse_excluded(path, key, excludes, found):
    for path_named, label in sorted(found.items()):
        for spec, dropped in excludes:
            if covers(dropped, path_named):
                problem(f"{key}'s `{spec}` drops {path_named}, which go names for {label}, from every release "
                        f"whatever else names it; narrow the exclude", path)


def legion(go):
    """The legion line: rules 1 to 3, and 5 and 6 for its listings."""
    text = read(RELEASE)
    lines = text.split("\n")
    doc = load(RELEASE, text)
    plain, excludes = pathspecs(RELEASE, doc, HAND)
    listings = [(["./cmd/legion"], {"GOOS": t.split("/")[0], "GOARCH": t.split("/")[1], "CGO_ENABLED": "0"},
                 f"./cmd/legion for {t}") for t in targets(TARGETS, "legion", pairs=True)]
    found = named(go, listings)
    refuse_excluded(RELEASE, HAND, excludes, found)
    report_and_stop_on_problems()

    inputs = sorted(path for path in found if not any(covers(spec, path) for spec in plain))
    body = [f"  {BLOCK}: >-", *(f"    {path}" for path in inputs)] if inputs else [f'  {BLOCK}: ""']
    want = [*HEAD, *body, END]
    begins = [i for i, line in enumerate(lines) if line.startswith(BEGIN)]
    if len(begins) != 1:
        fatal(f"{RELEASE} must hold one block from `{BEGIN.strip()}` to `{END.strip()}`, which {SELF} write "
              f"fills; it holds {len(begins)}", RELEASE)
    begin = begins[0]
    end = next((i for i in range(begin + 1, len(lines)) if lines[i] == END), None)
    if end is None:
        fatal(f"{RELEASE}'s block from line {begin + 1} has no `{END.strip()}` line", RELEASE)
    have = lines[begin:end + 1]
    if have != want:
        if MODE == "write":
            lines[begin:end + 1] = want
            text = "\n".join(lines)
            Path(RELEASE).write_text(text, encoding="utf-8")
            doc = load(RELEASE, text)
            print(f"wrote {RELEASE}'s {BLOCK}: {len(inputs)} paths")
        else:
            # The block's paths are its lines indented as the folded value's, comments aside.
            held = {line.strip() for line in have if line.startswith("    ") and not line.lstrip().startswith("#")}
            lacks = [path for path in inputs if path not in held]
            extra = sorted(held - set(inputs))
            parts = ([f"it lacks {', '.join(lacks)}, which go names"] if lacks else []) + (
                [f"it names {', '.join(extra)}, which go does not"] if extra else [])
            problem(f"{BLOCK} is not what go decides the legion binary from beyond {HAND}'s paths: "
                    f"{'; '.join(parts) or 'its text is not the block write writes'}; run `{SELF} write`",
                    RELEASE, line=begin + 1)
    elif MODE == "write":
        print(f"{RELEASE}'s {BLOCK} already holds what go names: {len(inputs)} paths")

    if have == want or MODE == "write":
        value = env_of(RELEASE, doc).get(BLOCK)
        if not isinstance(value, str) or value.split() != inputs:
            problem(f"the block from line {begin + 1} is not the {BLOCK} of {RELEASE}'s workflow env:, "
                    f"which legion_build's version step reads", RELEASE, line=begin + 1)

    jobs = doc.get("jobs") if isinstance(doc, dict) else None
    steps = ((jobs or {}).get(JOB) or {}).get("steps") or []
    runs = [step.get("run") for step in steps if isinstance(step, dict) and step.get("id") == STEP_ID]
    if len(runs) != 1 or not isinstance(runs[0], str) or HANDOFF not in " ".join(runs[0].split()):
        problem(f"{JOB}'s step `{STEP_ID}` must run `{HANDOFF}`: {BLOCK} decides a release only "
                f"where that step hands it to release-push.sh after {HAND}", RELEASE)
    packages = sum(path.endswith("/") for path in inputs)
    return (f"{RELEASE}'s {BLOCK} is what go decides the legion binary from beyond {HAND}'s paths: "
            f"{packages} package directories and {len(inputs) - packages} module files, over "
            f"{', '.join(label.removeprefix('./cmd/legion for ') for _, _, label in listings)}")


def legion_envoy(go):
    """The legion-envoy line: rules 4 to 6."""
    plain, excludes = pathspecs(LISTENER, load(LISTENER, read(LISTENER)), ENVOY_ARGS)
    listings = []
    for arch in targets(TARGETS, "envoy", pairs=False):
        for cgo in ("0", "1"):
            listings.append((["./cmd/listener"], {"GOOS": "linux", "GOARCH": arch, "CGO_ENABLED": cgo},
                             f"./cmd/listener for linux/{arch} with CGO_ENABLED={cgo}"))
        listings.append((["./cmd/agent-secrets", "./cmd/agent-secrets-helper"],
                         {"GOOS": "linux", "GOARCH": arch, "CGO_ENABLED": "0"},
                         f"./cmd/agent-secrets and ./cmd/agent-secrets-helper for linux/{arch}"))
    for target in targets(CLIENT_TARGETS, "agent-secrets-client", pairs=True):
        goos, goarch = target.split("/")
        listings.append((["./cmd/agent-secrets"], {"GOOS": goos, "GOARCH": goarch, "CGO_ENABLED": "0"},
                         f"./cmd/agent-secrets for {target}"))
    found = named(go, listings)
    refuse_excluded(LISTENER, ENVOY_ARGS, excludes, found)
    for path, label in sorted(found.items()):
        if not any(covers(dropped, path) for _, dropped in excludes) and not any(covers(spec, path) for spec in plain):
            problem(f"{ENVOY_ARGS} names no path that covers {path}, which go names for {label}, so a "
                    f"change to it releases nothing; add it after `--`", LISTENER)
    packages = sum(path.endswith("/") for path in found)
    return (f"{LISTENER}'s {ENVOY_ARGS} covers what go decides the archives from: {packages} package "
            f"directories and {len(found) - packages} module files, over {len(listings)} listings")


modcache = tempfile.mkdtemp(prefix="check-legion-version-inputs-")
try:
    verdicts = [legion(Go(DAEMON, modcache)), legion_envoy(Go(ENVOY, modcache))]
finally:
    shutil.rmtree(modcache, True)
report_and_stop_on_problems()
print("\n".join(verdicts))
PY
